public class Cookie {
    private String flavor;

    public Cookie(String flavor) {
        this.flavor = flavor;
    }

    public String getFlavor() {
        return flavor;
    }

    public String describe() {
        return "A classic " + flavor + " cookie.";
    }
}

public class DecoratedCookie extends Cookie {

    public DecoratedCookie(String flavor) {
        super(flavor);
    }

    @Override
    public String describe() {
        return "This " + getFlavor() + " cookie is decorated with sprinkles and icing!";
    }
}

public class GiftCookie extends Cookie {

    public GiftCookie(String flavor) {
        super(flavor);
    }

    @Override
    public String describe() {
        return "A " + getFlavor() + " cookie, ready to be wrapped as a gift.";
    }

    public String packageCookie() {
        return "Packaged " + getFlavor() + " cookie in a gift box.";
    }

    public String packageCookie(String giftNote) {
        return packageCookie() + " Gift note: " + giftNote;
    }
}
